const $=s=>document.querySelector(s), main=$('#main');
let state={known:[],errors:[],attempts:0,correct:0,days:[],daily:{},speaking:{}};
try{const saved=JSON.parse(localStorage.getItem('wordstep-v1'));if(saved&&typeof saved==='object'){state={...state,...saved};for(const k of ['known','errors','days'])if(!Array.isArray(state[k]))state[k]=[];for(const k of ['daily','speaking'])if(!state[k]||typeof state[k]!=='object')state[k]={};}}catch{}
const today=()=>new Date().toLocaleDateString('en-CA');
function save(){try{localStorage.setItem('wordstep-v1',JSON.stringify(state));}catch{toast('No se pudo guardar. Tu navegador puede tener el almacenamiento desactivado.');}$('#errorCount').textContent=state.errors.length;}
function track(){const d=today();if(!state.days.includes(d))state.days.push(d);state.daily[d]=(state.daily[d]||0)+1;save();}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',3000);}
function shuffle(a){a=[...a];for(let i=a.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function escapeHTML(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function title(kicker,name,sub){return `<div class="topline"><span class="eyebrow">${kicker}</span><span class="pill">INTERMEDIO · B1+</span></div><h1>${name}</h1><p class="subtitle">${sub}</p>`;}
let view='inicio',wordFilter='all',wordSearch='',wordPool=[],wordIndex=0,flipped=false,topic='wish',quiz=null,match=null,speakIndex=0;
function go(v){view=v;document.querySelectorAll('nav button').forEach(b=>{b.classList.toggle('active',b.dataset.view===v);b.setAttribute('aria-current',b.dataset.view===v?'page':'false');});render();save();}
function render(){({inicio:home,palabras:words,relacionar:matching,gramatica:grammar,hablar:speaking,repasar:review,progreso:progress}[view]||home)();}
function home(){const n=state.daily[today()]||0;main.innerHTML=title('UN POCO MEJOR, CADA DÍA','Tu próximo paso empieza aquí.','Practica palabras, entiende los patrones y llega con más confianza a tu examen.')+`<section class="hero"><div><span class="eyebrow">TU SESIÓN DE HOY · 15 MINUTOS</span><h2>Las palabras se aprenden.<br>La confianza se practica.</h2><p>Empieza con vocabulario útil, conecta ideas y pon a prueba lo que sabes. A tu ritmo.</p><button class="primary" data-action="start">Empezar a practicar <span aria-hidden="true">→</span></button></div><div class="hero-art" aria-hidden="true"><span class="spark">✦</span><div class="paper-card"><small>WORD OF THE DAY</small><strong>achieve</strong><span>lograr · alcanzar</span></div><div class="float-tag">Small steps, big progress. ↗</div></div></section><div class="stats"><div class="stat"><strong>${state.known.length}<small style="font-size:13px;color:var(--muted)"> / 60</small></strong><span>Palabras que ya conoces</span></div><div class="stat"><strong>${state.attempts?Math.round(state.correct/state.attempts*100):0}%</strong><span>Aciertos en ejercicios</span></div><div class="stat"><strong>${Math.min(n,15)}<small style="font-size:13px;color:var(--muted)"> / 15</small></strong><span>Prácticas de hoy</span></div></div><div class="section-head"><h2>Tus temas para el examen</h2><span>ENTIENDE → PRACTICA → RECUERDA</span></div><div class="grid">${Object.entries(TOPICS).map(([k,t])=>`<button class="topic" data-topic="${k}"><span class="icon">${t.icon}</span><span class="arrow">↗</span><h3>${t.title}</h3><p>${t.desc}</p></button>`).join('')}</div><p class="footer-tip">✦ Tu ruta: 5 palabras → relacionar significados → 10 preguntas → una respuesta en voz alta.</p>`;}
function filteredWords(){return WORDS.filter(w=>(wordFilter==='all'||(wordFilter==='pending'?!state.known.includes(w.id):w.cat===wordFilter))&&`${w.en} ${w.es}`.toLowerCase().includes(wordSearch.toLowerCase()));}
function words(){wordPool=filteredWords();if(wordIndex>=wordPool.length)wordIndex=0;main.innerHTML=title('CONSTRUYE TU VOCABULARIO','Una palabra. Más posibilidades.','Intenta recordar el significado antes de girar la tarjeta. Aprende cada palabra dentro de una frase.')+`<div class="toolbar"><label for="category">Tema</label><select id="category"><option value="all">Todas las palabras</option><option value="pending">Por aprender</option>${[...new Set(WORDS.map(w=>w.cat))].map(c=>`<option>${c}</option>`).join('')}</select><input id="search" aria-label="Buscar palabra" placeholder="Buscar en inglés o español…" value="${escapeHTML(wordSearch)}"></div><div id="wordCard"></div>`;$('#category').value=wordFilter;wordCard();}
function wordCard(){const w=wordPool[wordIndex];if(!w){$('#wordCard').innerHTML='<div class="card empty">No hay palabras en este filtro. Prueba otro tema.</div>';return;}$('#wordCard').innerHTML=`<div class="topline"><span class="muted">Palabra ${wordIndex+1} de ${wordPool.length}</span><span class="pill">${w.cat}</span></div><button class="card flash" style="width:100%" data-action="flip" aria-label="${flipped?'Ocultar':'Mostrar'} significado"><span class="eyebrow">${flipped?'SIGNIFICADO Y CONTEXTO':'¿RECUERDAS QUÉ SIGNIFICA?'}</span><h2 lang="en">${w.en}</h2>${flipped?`<div class="translation">${w.es}</div><p><span lang="en">${w.example}</span><br><span class="muted">${w.translation}</span></p>`:'<p class="muted">Toca para descubrir ↻</p>'}</button><div class="actions"><button data-action="wordPrev" aria-label="Palabra anterior">←</button><button data-action="wordAgain">Seguir repasando</button><button class="primary" data-action="wordKnow">${state.known.includes(w.id)?'Ya la conozco ✓':'Ya la sé ✓'}</button><button data-action="wordNext" aria-label="Palabra siguiente">→</button></div><p class="muted">“Ya la sé” es tu propia valoración. Refuérzala jugando a relacionar palabras.</p>`;}
function nextWord(delta=1){wordIndex=(wordIndex+delta+wordPool.length)%wordPool.length;flipped=false;wordCard();}
function newMatch(){const pending=WORDS.filter(w=>!state.known.includes(w.id));const pool=pending.length>=5?pending:WORDS;const batch=shuffle(pool).slice(0,5);match={batch,right:shuffle(batch),left:null,selectedRight:null,done:[],busy:false};}
function matching(){if(!match)newMatch();main.innerHTML=title('CONECTA LO QUE SABES','Encuentra su pareja.','Toca una palabra en inglés y luego su significado en español. No necesitas arrastrar.')+`<div class="card"><div class="topline"><h2>Relaciona las palabras</h2><span id="matchScore" class="pill">${match.done.length} / 5</span></div><div class="progress-track"><i style="width:${match.done.length*20}%"></i></div><div class="match-grid"><div class="match-column">${match.batch.map(w=>`<button lang="en" data-left="${w.id}" ${match.done.includes(w.id)?'disabled class="correct"':''}>${w.en}${match.done.includes(w.id)?' ✓':''}</button>`).join('')}</div><div class="match-column">${match.right.map(w=>`<button data-right="${w.id}" ${match.done.includes(w.id)?'disabled class="correct"':''}>${w.es}${match.done.includes(w.id)?' ✓':''}</button>`).join('')}</div></div><div id="matchFeedback" class="muted" role="status" style="margin-top:18px">${match.done.length===5?'¡Completaste la ronda! Prueba otras cinco palabras.':'Elige una palabra de cada columna.'}</div></div><button class="primary" data-action="matchNew">Otra ronda ↻</button>`;}
function chooseMatch(side,id){if(match.busy||match.done.includes(id))return;match[side==='left'?'left':'selectedRight']=id;document.querySelectorAll(`[data-${side}]`).forEach(b=>b.classList.toggle('picked',b.dataset[side]===id));if(!match.left||!match.selectedRight)return;const ok=match.left===match.selectedRight;state.attempts++;if(ok){state.correct++;match.done.push(id);state.errors=state.errors.filter(x=>x!==id);track();matching();}else{const wid=match.left;if(!state.errors.includes(wid))state.errors.push(wid);track();match.busy=true;$('#matchFeedback').textContent='Todavía no. Piensa en el significado e inténtalo otra vez.';document.querySelectorAll('.picked').forEach(b=>b.classList.add('incorrect'));const current=match;setTimeout(()=>{if(match!==current)return;match.busy=false;match.left=null;match.selectedRight=null;if(view==='relacionar')document.querySelectorAll('.picked').forEach(b=>b.classList.remove('picked','incorrect'));},850);}if(ok){match.left=null;match.selectedRight=null;}}
function grammar(){if(quiz){quizView();return;}main.innerHTML=title('ENTIENDE EL PATRÓN','Gramática que puedes usar.','Una explicación corta, ejemplos claros y práctica con retroalimentación en español.')+`<div class="chips">${Object.entries(TOPICS).map(([k,t])=>`<button data-topic="${k}" class="${k===topic?'selected':''}">${t.title}</button>`).join('')}</div><div class="card"><span class="pill">GUÍA RÁPIDA</span><h2>${TOPICS[topic].title}</h2>${TOPICS[topic].rules.map(r=>`<div class="rule"><strong>${r[0]}</strong><code>${r[1]}</code><p lang="en">${r[2]}</p><p class="muted">${r[3]}</p></div>`).join('')}</div><div class="actions"><button class="primary" data-action="quizTopic">Practicar este tema →</button><button data-action="quizMixed">Simulacro mixto · 12 preguntas</button></div>`;}
function startQuiz(items,label){quiz={items:shuffle(items).map(q=>({...q,options:shuffle(q.options)})),label,index:0,score:0,answered:false,picked:null};go('gramatica');}
function quizView(){const q=quiz.items[quiz.index];if(!q){main.innerHTML=title('SESIÓN COMPLETADA','Cada intento cuenta.','Revisa lo que te costó y vuelve a intentarlo.')+`<div class="card result"><span class="eyebrow">${quiz.label}</span><p class="score">${quiz.score} / ${quiz.items.length}</p><h2>${quiz.score/quiz.items.length>=.8?'¡Vas por buen camino!':'Ya sabes qué necesitas reforzar.'}</h2><p class="muted">Los fallos quedan en “Mis errores” para que puedas repasarlos.</p><div class="actions"><button class="primary" data-action="quizEnd">Volver a la guía</button><button data-view="repasar">Repasar errores →</button></div></div>`;return;}main.innerHTML=title('PONTE A PRUEBA',quiz.label,'Elige la mejor respuesta. Lee la explicación antes de continuar.')+`<div class="topline"><span class="muted">Pregunta ${quiz.index+1} de ${quiz.items.length}</span><button class="small" data-action="quizEnd">Volver a la guía</button></div><div class="progress-track"><i style="width:${quiz.index/quiz.items.length*100}%"></i></div><div class="card"><span class="pill">${q.topic==='vocab'?'VOCABULARIO':TOPICS[q.topic].title}</span><h2 class="question" lang="en">${q.prompt}</h2><div class="options">${q.options.map((o,i)=>`<button data-answer="${i}" ${quiz.answered?'disabled':''} class="${quiz.answered?(o===q.answer?'correct':o===quiz.picked?'incorrect':''):''}"><span class="pill">${String.fromCharCode(65+i)}</span> ${o}</button>`).join('')}</div>${quiz.answered?`<div class="feedback" role="status"><strong>${quiz.picked===q.answer?'✓ ¡Correcto!':'Vamos a reforzarlo.'}</strong><p>Respuesta: <b>${q.answer}</b></p><p>${q.explanation}</p></div><div class="actions"><button class="primary" data-action="quizNext">${quiz.index===quiz.items.length-1?'Ver resultado':'Siguiente'} →</button></div>`:''}</div>`;}
function answer(i){if(!quiz||quiz.answered)return;const q=quiz.items[quiz.index];quiz.picked=q.options[i];quiz.answered=true;state.attempts++;if(quiz.picked===q.answer){state.correct++;quiz.score++;state.errors=state.errors.filter(id=>id!==q.id);}else if(!state.errors.includes(q.id))state.errors.push(q.id);track();quizView();}
function review(){const items=state.errors.map(id=>QUESTIONS.find(q=>q.id===id)||WORDS.find(w=>w.id===id)).filter(Boolean);main.innerHTML=title('REPETIR TAMBIÉN ES AVANZAR','Dale otra oportunidad.','Los errores de gramática y de vocabulario aparecen aquí. Acertar en el repaso los retira de esta lista.')+(items.length?`<div class="card"><h2>${items.length} ${items.length===1?'concepto para repasar':'conceptos para repasar'}</h2><div class="word-list">${items.map(x=>`<div class="word-row"><span>${x.en||x.prompt}</span><span class="pill">${x.en?'Palabra':TOPICS[x.topic].title}</span></div>`).join('')}</div></div><button class="primary" data-action="reviewStart">Repasar mis errores →</button>`:'<div class="card empty"><strong>✦</strong><h2>Por aquí, todo despejado.</h2><p class="muted">Practica gramática o relaciona palabras. Si algo cuesta, lo guardamos aquí.</p><button class="primary" data-view="gramatica">Practicar gramática →</button></div>');}
function reviewQuiz(){const items=state.errors.map(id=>{const q=QUESTIONS.find(x=>x.id===id);if(q)return q;const w=WORDS.find(x=>x.id===id);return w?{id:w.id,topic:'vocab',prompt:`What does “${w.en}” mean?`,options:shuffle([w.es,...shuffle(WORDS.filter(x=>x.id!==w.id)).slice(0,2).map(x=>x.es)]),answer:w.es,explanation:`${w.example} — ${w.translation}`}:null;}).filter(Boolean);if(items.length)startQuiz(items,'Repaso de mis errores');}
function speaking(){const p=SPEAKING[speakIndex];main.innerHTML=title('DEL CONOCIMIENTO A LA CONVERSACIÓN','Ahora dilo con tus palabras.','Lee la pregunta y responde en voz alta durante 30–60 segundos. Sin audio ni micrófono: tú marcas el ritmo.')+`<div class="card"><div class="topline"><span class="pill">${TOPICS[p[3]].title}</span><span class="muted">${speakIndex+1} / ${SPEAKING.length}</span></div><h2 class="question" lang="en">${p[0]}</h2><p class="muted">Empieza con: <b lang="en">${p[1]}</b></p><label for="speakingNotes">Escribe tu borrador si te ayuda:</label><textarea id="speakingNotes" placeholder="Organiza tus ideas aquí…">${escapeHTML(state.speaking[speakIndex]||'')}</textarea><details><summary>Ver una respuesta modelo</summary><p lang="en">${p[2]}</p><p class="muted">Es un ejemplo, no la única respuesta correcta. Tus notas se guardan, pero no se califican automáticamente.</p></details><div class="feedback"><strong>Tu lista de práctica</strong><p>□ Usé el patrón del tema.<br>□ Respondí la pregunta y expliqué por qué.<br>□ Intenté usar una palabra nueva.</p></div></div><div class="actions"><button data-action="speakPrev">← Anterior</button><button class="primary" data-action="speakDone">Ya lo practiqué ✓</button><button data-action="speakNext">Otra pregunta →</button></div>`;}
function progress(){main.innerHTML=title('MIRA LO QUE YA AVANZASTE','Tu esfuerzo se va sumando.','Este registro pertenece a este navegador; otros dispositivos tendrán su propio progreso.')+`<div class="stats"><div class="stat"><strong>${state.known.length}</strong><span>Palabras conocidas</span></div><div class="stat"><strong>${state.correct} / ${state.attempts}</strong><span>Aciertos / intentos</span></div><div class="stat"><strong>${state.days.length}</strong><span>Días de práctica</span></div></div><div class="card"><h2>Tus palabras conocidas</h2>${state.known.length?`<div class="word-list">${WORDS.filter(w=>state.known.includes(w.id)).map(w=>`<div class="word-row"><b>${w.en}</b><span>${w.es}</span></div>`).join('')}</div>`:'<p class="muted">Marca “Ya la sé” en las tarjetas para ver tus palabras aquí.</p>'}</div><button data-view="palabras" class="primary">Seguir aprendiendo →</button>`;}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.view){if(b.dataset.view==='gramatica')quiz=null;go(b.dataset.view);return;}if(b.dataset.topic){topic=b.dataset.topic;quiz=null;go('gramatica');return;}if(b.dataset.answer!==undefined){answer(Number(b.dataset.answer));return;}if(b.dataset.left){chooseMatch('left',b.dataset.left);return;}if(b.dataset.right){chooseMatch('right',b.dataset.right);return;}const a=b.dataset.action;if(a==='start'){wordFilter='pending';wordSearch='';wordIndex=0;flipped=false;go('palabras');}if(a==='flip'){flipped=!flipped;wordCard();}if(a==='wordNext')nextWord();if(a==='wordPrev')nextWord(-1);if(a==='wordKnow'||a==='wordAgain'){const w=wordPool[wordIndex];if(!w)return;if(a==='wordKnow'&&!state.known.includes(w.id))state.known.push(w.id);if(a==='wordAgain')state.known=state.known.filter(id=>id!==w.id);track();toast(a==='wordKnow'?'¡Una palabra más en tu vocabulario!':'La seguiremos practicando.');if(wordFilter==='pending'){flipped=false;words();}else nextWord();}if(a==='matchNew'){newMatch();matching();}if(a==='quizTopic')startQuiz(QUESTIONS.filter(q=>q.topic===topic),TOPICS[topic].title);if(a==='quizMixed')startQuiz(Object.keys(TOPICS).flatMap(t=>shuffle(QUESTIONS.filter(q=>q.topic===t)).slice(0,3)),'Simulacro mixto');if(a==='quizNext'){quiz.index++;quiz.answered=false;quiz.picked=null;quizView();}if(a==='quizEnd'){quiz=null;grammar();}if(a==='reviewStart')reviewQuiz();if(a==='speakNext'||a==='speakDone'||a==='speakPrev'){if(a==='speakDone'){track();toast('¡Bien! Cada respuesta te da más práctica.');}speakIndex=(speakIndex+(a==='speakPrev'?-1:1)+SPEAKING.length)%SPEAKING.length;speaking();}});
document.addEventListener('change',e=>{if(e.target.id==='category'){wordFilter=e.target.value;wordIndex=0;flipped=false;words();}});
document.addEventListener('input',e=>{if(e.target.id==='search'){wordSearch=e.target.value;wordIndex=0;flipped=false;wordPool=filteredWords();wordCard();}if(e.target.id==='speakingNotes'){state.speaking[speakIndex]=e.target.value;save();}});
$('#progressButton').onclick=()=>go('progreso');$('.brand').onclick=e=>{e.preventDefault();go('inicio');};go('inicio');
